<template><main><div class="patient-context">当前患者：{{name}}</div><div v-if="!visits.length" class="empty">暂无随访记录</div><div v-else class="list"><button v-for="v in visits" :key="v.id||v.date" class="card visit-card"><div><div class="visit-label">随访日期</div><div class="visit-date">{{v.date}}</div></div><div class="chev">›</div></button></div></main><div class="fabbar"><button class="primary" @click="showToast('新增随访接口待接入')">新增随访记录</button></div><div v-if="toast" class="toast show">{{toast}}</div></template>
<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {initLeftTitle,registerNativeBack} from '../native/bridge';const route=useRoute(),router=useRouter();const name=computed(()=>route.query.name||'患者');const visits=ref([]),toast=ref('');function showToast(t){toast.value=t;setTimeout(()=>toast.value='',1500)}let cleanup;onMounted(()=>{initLeftTitle(2,'随访记录');cleanup=registerNativeBack(()=>router.back())});onUnmounted(()=>cleanup?.())
</script>
